'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('smbus-book-v1')||'{}');}catch{saved={};}if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};saved.done=Array.isArray(saved.done)?saved.done:[];saved.notes=saved.notes&&typeof saved.notes==='object'?saved.notes:{};saved.checks=Array.isArray(saved.checks)?saved.checks:[];
let cleanup=()=>{};const save=()=>{try{localStorage.setItem('smbus-book-v1',JSON.stringify(saved));}catch{toast('브라우저 저장 공간을 사용할 수 없습니다.');}};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2200);}
const lab=(name,body)=>`<section class="lab"><div class="lab-title">${name}<span>INTERACTIVE LAB</span></div><div class="lab-body">${body}</div></section>`;
const scope=(id,label,caption)=>`<div class="scope"><div class="scope-head"><span>${label}</span><b>SMBCLK / SMBDAT</b></div><div class="wave-scroll" id="${id}"></div><div class="scope-caption">${caption}</div></div>`;
const input=(id,label,value,min,max,step=1)=>`<div class="control"><label for="${id}">${label}<output id="${id}-out">${value}</output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
function bindRange(id,fn,unit=''){const e=$('#'+id);const f=()=>{$('#'+id+'-out').textContent=e.value+unit;fn(+e.value);};e.oninput=f;f();}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function nav(){const id=location.hash.slice(1)||'intro';$('#nav').innerHTML=chapters.map((c,i)=>(c.group?`<div class="nav-group">${c.group}</div>`:'')+`<a href="#${c.id}" class="${c.id===id?'active':''}" ${c.id===id?'aria-current="page"':''}><span class="num">${String(i+1).padStart(2,'0')}</span>${c.title}<span class="tick">${saved.done.includes(c.id)?'✓':''}</span></a>`).join('');$('#progress').value=saved.done.length;$('#progress-text').textContent=`${saved.done.length} / ${chapters.length}`;}
function render(){cleanup();cleanup=()=>{};$('#search').value='';const id=location.hash.slice(1)||'intro',c=chapters.find(c=>c.id===id)||chapters[0],i=chapters.indexOf(c);nav();$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');document.title=c.title+' · SMBus Lab';$('#main').innerHTML=`<div class="breadcrumb"><span>SMBus Lab / ${String(i+1).padStart(2,'0')} ${c.title}</span><span>${c.section}</span></div>${i?`<div class="eyebrow">CHAPTER ${String(i+1).padStart(2,'0')} / SMBUS 3.3</div><h1>${c.title}</h1><p class="section-intro">${c.desc}</p>`:''}${c.body()}<section class="chapter-footer"><div class="row"><h3>나의 학습 노트</h3><button class="btn" id="complete">${saved.done.includes(c.id)?'✓ 학습 완료 · 취소':'이 장 학습 완료'}</button></div><label for="notes">궁금한 점, 실측 결과, 다시 확인할 규칙</label><textarea id="notes" placeholder="예: tHD:DAT=0이어도 송신 측 pin의 실제 threshold 순서를 확인해야 한다."></textarea><div class="bottom-nav">${i?`<a class="btn" href="#${chapters[i-1].id}">← ${chapters[i-1].title}</a>`:'<span></span>'}${i<chapters.length-1?`<a class="btn primary" href="#${chapters[i+1].id}">${chapters[i+1].title} →</a>`:'<a class="btn" href="#intro">처음으로 ↑</a>'}</div><p class="footnote">SMBus Lab · 학습용 해설과 계산 모델 · 규범적 판단은 SMBus 3.3 원문과 장치 문서 확인</p></section>`;$('#notes').value=typeof saved.notes[c.id]==='string'?saved.notes[c.id]:'';$('#notes').oninput=e=>{saved.notes[c.id]=e.target.value;save();};$('#complete').onclick=()=>{saved.done=saved.done.includes(c.id)?saved.done.filter(x=>x!==c.id):[...saved.done,c.id];save();nav();$('#complete').textContent=saved.done.includes(c.id)?'✓ 학습 완료 · 취소':'이 장 학습 완료';};const inits={intro:initHero,physical:initPhysical,timing:initTiming,link:initLink,arbitration:initArb,protocols:initProtocol,pec:initPec,address:initAddress,arp:initArp,signals:initAlert,verification:initCheck};inits[c.id]?.();window.scrollTo(0,0);}
function svgWrap(content,w=800,h=230){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="SMBus 학습 파형"><defs><pattern id="grid" width="40" height="30" patternUnits="userSpaceOnUse"><path d="M 40 0 L 0 0 0 30" fill="none" stroke="#243242" stroke-width=".6"/></pattern><marker id="arrow" markerWidth="6" markerHeight="6" refX="3" refY="3" orient="auto-start-reverse"><path d="M0 0 L6 3 L0 6" fill="#f5c77e"/></marker></defs><rect width="${w}" height="${h}" fill="#101b27"/><rect width="${w}" height="${h}" fill="url(#grid)"/>${content}</svg>`;}
const txt=(x,y,s,color='#a3b3c7',size=11)=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}">${esc(s)}</text>`;
const path=(d,col='#76dfba')=>`<path d="${d}" fill="none" stroke="${col}" stroke-width="2.5" stroke-linejoin="round"/>`;
function byteWave(value,ack=true){let s=txt(20,58,'CLK')+txt(20,140,'DAT'),clk='M80 48',dat='M80 128',bits=Array.from({length:8},(_,i)=>(value>>(7-i))&1);bits.push(ack?0:1);for(let i=0;i<9;i++){let x=85+i*70,y=bits[i]?128:165;clk+=` H${x} V84 H${x+28} V48 H${x+70}`;dat+=` H${x+12} V${y} H${x+70}`;s+=txt(x+32,110,i===8?(ack?'ACK':'NACK'):'b'+(7-i),i===8?'#f5c77e':'#a3b3c7',10)+txt(x+36,195,String(bits[i]),'#7cb0ff');}return svgWrap(s+path(clk)+path(dat,'#82aaff'));}
function initHero(){let v=0xa6;const draw=()=>{$('#hero-wave').innerHTML=byteWave(v);$('#hero-bits').innerHTML=Array.from({length:8},(_,i)=>`<button class="bit ${(v>>(7-i))&1?'on':''}" aria-label="bit ${7-i} 전환" data-bit="${7-i}">${(v>>(7-i))&1}</button>`).join('')+`<span class="mono" style="margin:auto 8px">0x${SMB.hex(v)}</span>`;$('#hero-bits').querySelectorAll('button').forEach(b=>b.onclick=()=>{v^=1<<+b.dataset.bit;draw();});};draw();}
function initPhysical(){let a=false,b=false;$('#open-drain').innerHTML=lab('Open-drain 스위치',`<div class="toolbar"><button class="btn" id="drain-a"></button><button class="btn" id="drain-b"></button></div><div id="drain-result"></div>`);const draw=()=>{$('#drain-a').textContent=`장치 A · ${a?'LOW 구동':'해제 (Z)'}`;$('#drain-b').textContent=`장치 B · ${b?'LOW 구동':'해제 (Z)'}`;$('#drain-result').innerHTML=`<div class="metric">BUS = ${a||b?'0 · LOW':'1 · HIGH'}</div><p class="hint">${a||b?'하나 이상의 pull-down이 활성화되어 전류가 흐릅니다.':'두 장치 모두 출력을 놓아 pull-up이 선을 HIGH로 만듭니다.'}</p>`;};$('#drain-a').onclick=()=>{a=!a;draw();};$('#drain-b').onclick=()=>{b=!b;draw();};draw();
$('#rc-lab').innerHTML=lab('RC rise-time explorer',`<div class="controls">${input('resistor','Pull-up R (Ω)',2200,500,20000,100)}${input('cap','Bus C (pF)',100,10,500,10)}${input('vdd','Pull-up VDD (V)',3.3,1.8,5,.1)}</div>${scope('rc-wave','ANALOG MODEL / EXPONENTIAL RISE','RC 1차 근사 · 출력 transistor, 누설, current-source pull-up은 모델에 포함하지 않음')}<div id="rc-result"></div>`);const calc=()=>{let r=+$('#resistor').value,c=+$('#cap').value,v=+$('#vdd').value,tau=r*c*.001,rise=SMB.rcRise(r,c,v),max=tau*3;let d='';for(let i=0;i<=200;i++){const x=80+i*3.3,y=195-(v*(1-Math.exp(-(i/200*max)/tau)))/5*160;d+=(i?' L':'M')+x+' '+y;}let g=path(d)+txt(20,30,'V');[.65,1.5,v].forEach(n=>{let y=195-n/5*160;g+=`<path d="M80 ${y} H750" stroke="#5c7389" stroke-dasharray="4 4"/>`+txt(12,y+4,n.toFixed(2));});g+=txt(80,220,'0')+txt(590,220,Math.round(max)+' ns');$('#rc-wave').innerHTML=svgWrap(g);$('#rc-result').innerHTML=`<p class="metric">tR ≈ ${rise.toFixed(1)} ns</p><p class="hint">tR = R × C × ln[(VDD − 0.65) / (VDD − 1.50)]</p>`+table(['클래스','tR 최대','모델 비교'],[1000,300,120].map((m,i)=>[['100 kHz','400 kHz','1 MHz'][i],m+' ns',`<b class="${rise<=m?'good':'bad'}">${rise<=m?'PASS':'FAIL'}</b>`]))+`<p class="hint">VOL=0.4 V 가정 시 저항 전류 ≈ ${((v-.4)/r*1000).toFixed(2)} mA. Rise만 맞아도 Low Power pull-up current 또는 sink 조건은 위반할 수 있습니다.</p>`;};['resistor','cap','vdd'].forEach(id=>bindRange(id,calc));}
function initTiming(){let cls=0,selected='tLOW',values={};function defaults(){values={};SMB.timing.forEach(t=>values[t.id]=t.min?.[cls]??t.max?.[cls]??0);values.tLOW=[5,1.4,.55][cls];values.tHIGH=[4.5,.8,.3][cls];values.tR=[250,150,70][cls];values.tF=[100,100,60][cls];}defaults();$('#timing-lab').innerHTML=lab('Timing explorer',`<div class="toolbar"><label>속도 클래스<select id="speed"><option>100 kHz</option><option>400 kHz</option><option>1 MHz</option></select></label><label>측정 항목<select id="parameter">${SMB.timing.slice(0,10).map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${t.id} · ${t.name}</option>`).join('')}</select></label><button class="btn" id="timing-reset">권장 예제 복원</button><button class="btn" id="timing-fail">위반 예제</button></div>${scope('timing-wave','TIMING MEASUREMENT / SCHEMATIC','노란 화살표: 선택한 시간 간격 · 에지 위치를 단순화한 개략도')}<div class="controls" id="timing-controls"></div><div id="timing-explain" aria-live="polite"></div><div id="timing-table"></div><button class="btn" id="timing-export">설정·판정 JSON 저장</button>`);
function controls(){const t=SMB.timing.find(t=>t.id===selected),base=t.min?.[cls]||t.max?.[cls]||100;$('#timing-controls').innerHTML=input('timing-value',`${t.id} (${t.unit})`,values[t.id],0,Math.max(base*2,base+1,(t.max?.[cls]||0)*1.2),t.unit==='µs'?.01:1);bindRange('timing-value',v=>{values[selected]=v;draw();},' '+t.unit);}
function draw(){const t=SMB.timing.find(t=>t.id===selected),v=values[selected],j=SMB.judge(t,cls,v),lo=t.min?.[cls],hi=t.max?.[cls];$('#timing-explain').innerHTML=`<p><b class="${j==='pass'?'good':'bad'}">${j==='pass'?'PASS':'FAIL'}</b> · <b>${t.id} = ${v} ${t.unit}</b> · 허용 ${lo==null?'최소 미규정':`최소 ${lo}`} / ${hi==null?'최대 미규정':`최대 ${hi}`} ${t.unit}</p><p class="compact">${t.desc}</p>`;
let x1=250,x2=480,clk='',dat='',label=t.id;const len=30+Math.min(1,v/(Math.max(lo||hi||100,1)*2))*300;
if(['tLOW','tHIGH'].includes(selected)){x1=260;x2=x1+len;clk=selected==='tLOW'?`M80 55 H260 V95 H${x2} V55 H750`:`M80 95 H260 V55 H${x2} V95 H750`;dat='M80 175 H130 V140 H730';}
else if(['tSU:DAT','tHD:DAT'].includes(selected)){if(selected==='tSU:DAT'){x2=550;x1=x2-len;clk='M80 95 H550 V55 H700 V95 H750';dat=`M80 175 H${x1} V140 H750`;}else{x1=230;x2=x1+len;clk='M80 55 H230 V95 H650 V55 H750';dat=`M80 140 H${x2} V175 H750`;}}
else if(['tR','tF'].includes(selected)){x1=260;x2=x1+len;clk=selected==='tR'?`M80 95 H260 L${x2} 55 H750`:`M80 55 H260 L${x2} 95 H750`;dat='M80 160 H750';label+=' (0.65 ↔ 1.50 V)';}
else if(selected==='tBUF'){x1=200;x2=x1+len;clk='M80 95 H140 V55 H700 V95 H750';dat=`M80 175 H200 V140 H${x2} V175 H750`;}
else if(selected==='tHD:STA'){x1=240;x2=x1+len;clk=`M80 55 H${x2} V95 H750`;dat='M80 140 H240 V175 H750';}
else{x1=240;x2=x1+len;clk='M80 95 H240 V55 H750';dat=selected==='tSU:STO'?`M80 175 H${x2} V140 H750`:`M80 175 H150 V140 H${x2} V175 H750`;}
let g=txt(15,75,'CLK')+txt(15,160,'DAT')+path(clk)+path(dat,'#82aaff');g+=`<path d="M${x1} 30 V190 M${x2} 30 V190" stroke="#f5c77e" stroke-dasharray="3 4"/><path d="M${x1} 207 H${x2}" stroke="#f5c77e" marker-start="url(#arrow)" marker-end="url(#arrow)"/>`+txt(260,250,label+' = '+v+' '+t.unit,'#f5c77e');$('#timing-wave').innerHTML=svgWrap(g,800,280);
const period=values.tLOW+values.tHIGH+(values.tR+values.tF)/1000,f=1000/period;$('#timing-table').innerHTML=`<p class="hint">간이 주기 모델: LOW + HIGH + rise + fall = ${period.toFixed(3)} µs → ${f.toFixed(1)} kHz. 실제 fSMB는 반복 클럭 주기를 직접 측정합니다.</p>`+table(['선택','기호 / 의미','최소','최대','단위'],SMB.timing.map(t=>[SMB.timing.indexOf(t)<10?`<button class="link" data-param="${t.id}">↗</button>`:'—',t.id+'<br><small>'+t.name+'</small>',t.min?.[cls]??'—',t.max?.[cls]??'—',t.unit]))+`<p class="hint">fSMB: 10–${[100,400,1000][cls]} kHz. tTIMEOUT는 검출/복귀 구간, tSPIKE는 제거 능력, tPOR는 최대 operational 시간입니다. “—”는 해당 표 칸 미규정이며 무제한 보증이 아닙니다.</p>`;$('#timing-table').querySelectorAll('[data-param]').forEach(b=>b.onclick=()=>{selected=b.dataset.param;$('#parameter').value=selected;controls();});}
$('#speed').onchange=e=>{cls=e.target.selectedIndex;defaults();controls();};$('#parameter').onchange=e=>{selected=e.target.value;controls();};$('#timing-reset').onclick=()=>{defaults();controls();};$('#timing-fail').onclick=()=>{const t=SMB.timing.find(t=>t.id===selected);if(t.min?.[cls]>0)values[selected]=+(t.min[cls]*.6).toFixed(2);else if(t.max?.[cls]!=null)values[selected]=t.max[cls]*1.4;else {selected='tSU:DAT';$('#parameter').value=selected;values[selected]=0;}controls();};$('#timing-export').onclick=()=>download('smbus-timing.json',JSON.stringify({spec:'SMBus 3.3',speedKHz:[100,400,1000][cls],values,scope:'educational scalar limits only'},null,2),'application/json');controls();}
function initLink(){$('#link-lab').innerHTML=lab('9번째 클럭의 주인',`<div class="toolbar"><label>전송 byte (16진수)<input type="text" id="link-byte" value="A6" maxlength="2" size="5"></label><label>수신 응답<select id="link-ack"><option>ACK</option><option>NACK</option></select></label><label>방향<select id="link-dir"><option>Controller → Target</option><option>Target → Controller</option></select></label></div>${scope('link-wave','BIT 7 → BIT 0 → ACK/NACK','전이 위치는 개략도 · 데이터는 클럭 HIGH 동안 안정')}<p id="link-note"></p>`);const f=()=>{if(!/^[0-9a-f]{1,2}$/i.test($('#link-byte').value)){$('#link-note').textContent='00–FF를 입력하세요.';return;}$('#link-wave').innerHTML=byteWave(parseInt($('#link-byte').value,16),$('#link-ack').selectedIndex===0);$('#link-note').textContent=`9번째 클럭의 SMBDAT 응답 담당: ${$('#link-dir').selectedIndex?'Controller':'Target'}. ${$('#link-ack').selectedIndex?'송신기는 놓고, 수신기도 HIGH로 해제합니다.':'송신기는 놓고, 수신기가 LOW로 당깁니다.'}`;};['link-byte','link-ack','link-dir'].forEach(id=>$('#'+id).oninput=f);f();}
function initArb(){$('#arb-lab').innerHTML=lab('비파괴 중재 · 1바이트 비교',`<div class="toolbar"><label>Controller A byte (hex)<input id="arb-a" value="A6" maxlength="2" size="5" type="text"></label><label>Controller B byte (hex)<input id="arb-b" value="A2" maxlength="2" size="5" type="text"></label></div><div id="arb-result"></div>`);const f=()=>{const a=$('#arb-a').value,b=$('#arb-b').value;if(!/^[a-f0-9]{1,2}$/i.test(a)||!/^[a-f0-9]{1,2}$/i.test(b)){$('#arb-result').textContent='00–FF의 바이트를 입력하세요.';return;}const r=SMB.arbitration(parseInt(a,16),parseInt(b,16));$('#arb-result').innerHTML=table(['','bit7','bit6','bit5','bit4','bit3','bit2','bit1','bit0'],[['A 전송 의도',...r.rows.map(x=>x.a)],['B 전송 의도',...r.rows.map(x=>x.b)],['실제 버스',...r.rows.map(x=>`<b>${x.bus}</b>`)],['A 참여',...r.rows.map(x=>x.aliveA?'계속':'해제')],['B 참여',...r.rows.map(x=>x.aliveB?'계속':'해제')]])+`<p class="metric">${r.loss<0?'아직 중재 미결정':r.winner+' 승리 · bit '+(7-r.loss)}</p><p class="hint">패배 이후의 “전송 의도”는 비교용 원래 값입니다. 실제 출력은 해제되어 승자의 값을 바꾸지 않습니다.</p>`;};$('#arb-a').oninput=f;$('#arb-b').oninput=f;f();$('#timeout-lab').innerHTML=lab('세 개의 시간계',`<div class="controls">${input('single-low','연속 LOW (ms)',20,0,45,.5)}${input('target-ext','Target 누적 연장 (ms)',20,0,40,.5)}${input('controller-ext','Controller 한 byte 구간 연장 (ms)',7,0,20,.5)}</div><div id="timeout-result" aria-live="polite"></div>`);const t=()=>{const a=+$('#single-low').value,b=+$('#target-ext').value,c=+$('#controller-ext').value;$('#timeout-result').innerHTML=table(['시간계','결과'],[['연속 LOW',a<=25?'25 ms 이하: timeout 판정 시작 전':a<35?'25 ms 초과: abort / reset 검출 구간':'35 ms 이상: 검출 장치는 새 START 수신 준비 완료 필요'],['Target 누적',`<span class="${b<=25?'good':'bad'}">${b<=25?'한계 내':'25 ms 초과'}</span>`],['Controller 누적',`<span class="${c<=10?'good':'bad'}">${c<=10?'한계 내':'10 ms 초과'}</span>`]])+`<p class="hint">서로 독립적인 가상 측정 사례입니다. 25–35 ms를 일반 clock LOW의 “정상 허용 폭”으로 판정하지 않습니다.</p>`;};['single-low','target-ext','controller-ext'].forEach(id=>bindRange(id,t));}
function eventWave(label){const start=label!=='STOP';return svgWrap(txt(20,70,'CLK')+txt(20,150,'DAT')+path('M80 55 H720')+path(start?'M80 130 H380 V170 H720':'M80 170 H380 V130 H720','#82aaff')+txt(310,215,label,'#f5c77e',16));}
function initProtocol(){let packet,step=0,timer=null;$('#protocol-lab').innerHTML=lab('Protocol builder & player',`<div class="toolbar"><label>프로토콜<select id="proto">${SMB.protocols.map(p=>`<option value="${p.id}" ${p.id==='readWord'?'selected':''}>${p.name}</option>`).join('')}</select></label><label>7-bit 주소 (hex)<input type="text" id="p-addr" value="0B" maxlength="2" size="5"></label><label>Command (hex)<input type="text" id="p-cmd" value="09" maxlength="2" size="5"></label><label><input type="checkbox" id="p-pec" checked> PEC 포함</label><label id="quick-wrap" hidden><input id="quick-read" type="checkbox"> Quick R/W=1</label></div><div class="toolbar"><label>Data pattern (wire 순서, hex)<input id="p-data" type="text" value="34 12 56 78 9A BC DE F0" size="30"></label><label id="count-wrap">Block count / M<input id="p-count" type="number" min="0" max="255" value="3"></label><label id="rcount-wrap">Read N<input id="p-rcount" type="number" min="0" max="255" value="2"></label></div><p id="p-desc" class="compact"></p><div id="p-error" role="status" class="bad"></div><div class="tokens" id="p-tokens"></div><div class="toolbar"><button class="btn primary" id="p-play">▶ 재생</button><button class="btn" id="p-back">← 이전</button><button class="btn" id="p-next">다음 →</button><button class="btn" id="p-reset">처음</button><label>위치<input type="range" id="p-position" min="0" value="0"></label></div>${scope('p-wave','SELECTED SEGMENT / BIT VIEW','바이트 안은 MSB first · token을 누르면 해당 구간과 9번째 응답을 표시')}<p id="p-detail" aria-live="polite"></p><p id="p-crc" class="mono compact"></p><div class="actions"><button class="btn" id="p-export">패킷 JSON 저장</button><button class="btn" id="p-svg">현재 파형 SVG 저장</button></div><p class="hint">입력 pattern이 전송 길이보다 짧으면 반복하여 예제 데이터를 만듭니다. 모델은 정상 ACK 흐름을 생성하며 실제 장치 동작을 대체하지 않습니다.</p>`);
function stop(){clearInterval(timer);timer=null;$('#p-play').textContent='▶ 재생';}cleanup=()=>clearInterval(timer);
function build(){stop();try{const id=$('#proto').value,p=SMB.protocols.find(x=>x.id===id),forbid=['quick','host'].includes(id);$('#p-pec').disabled=forbid;$('#quick-wrap').hidden=id!=='quick';$('#p-cmd').disabled=['quick','host','send','receive'].includes(id);$('#p-data').disabled=id==='quick';$('#count-wrap').hidden=!id.startsWith('block');$('#rcount-wrap').hidden=id!=='blockProcess';const addr=$('#p-addr').value,cmd=$('#p-cmd').value;if(!/^[a-f0-9]{1,2}$/i.test(addr)||parseInt(addr,16)>127)throw Error('주소는 00–7F 범위의 7비트 hex 값입니다.');if(!/^[a-f0-9]{1,2}$/i.test(cmd))throw Error('Command는 00–FF입니다.');const count=+$('#p-count').value,rcount=+$('#p-rcount').value;if(![count,rcount].every(n=>Number.isInteger(n)&&n>=0&&n<=255))throw Error('Block count는 0–255 정수입니다.');packet=SMB.packet(id,{addr:parseInt(addr,16),cmd:parseInt(cmd,16),data:SMB.parseBytes($('#p-data').value),count,rcount,pec:$('#p-pec').checked,quickRead:$('#quick-read').checked});step=0;$('#p-position').max=packet.tokens.length-1;$('#p-error').textContent='';$('#p-desc').innerHTML=p.desc+` <a href="${SMB.PDF}#page=${p.page}" target="_blank" rel="noopener">원문 p.${p.page} ↗</a>`;draw();}catch(e){packet=null;$('#p-error').textContent=e.message;$('#p-tokens').innerHTML='';$('#p-wave').innerHTML='';$('#p-detail').textContent='입력을 수정하면 다시 생성됩니다.';$('#p-crc').textContent='';}}
function draw(){if(!packet)return;const t=packet.tokens[step];$('#p-position').value=step;$('#p-tokens').innerHTML=packet.tokens.map((t,i)=>`<button class="token ${t.owner==='Target'?'target':''} ${step===i?'active':''}" data-i="${i}" aria-pressed="${step===i}">${t.label}<small>${t.kind==='byte'?'0x'+SMB.hex(t.value):t.owner}</small></button>`).join('');$('#p-tokens').querySelectorAll('button').forEach(b=>b.onclick=()=>{stop();step=+b.dataset.i;draw();});if(t.kind==='byte')$('#p-wave').innerHTML=byteWave(t.value,packet.tokens[step+1]?.label!=='NACK');else if(t.kind==='event')$('#p-wave').innerHTML=eventWave(t.label);else $('#p-wave').innerHTML=svgWrap(txt(20,70,'CLK')+txt(20,150,'DAT')+path('M80 95 H300 V55 H550 V95 H740')+path(`M80 ${t.value?135:175} H740`,'#82aaff')+txt(300,220,t.label+' · '+t.owner,'#f5c77e',16));$('#p-detail').textContent=`${step+1} / ${packet.tokens.length} · ${t.label} · ${t.owner} 구동${t.kind==='byte'?' · 0x'+SMB.hex(t.value)+' / '+t.value.toString(2).padStart(8,'0'):''}`;$('#p-crc').textContent=packet.pec?`PEC = 0x${SMB.hex(packet.crc)} · CRC 포함 byte ${packet.bytes.length}개`:'이 패킷에는 PEC가 없습니다.';}
['proto','p-addr','p-cmd','p-data','p-count','p-rcount','p-pec','quick-read'].forEach(id=>$('#'+id).oninput=build);$('#p-play').onclick=()=>{if(!packet)return;if(timer){stop();return;}if(step===packet.tokens.length-1)step=0;$('#p-play').textContent='Ⅱ 일시정지';draw();timer=setInterval(()=>{if(step<packet.tokens.length-1){step++;draw();}else stop();},750);};$('#p-next').onclick=()=>{stop();if(packet){step=Math.min(step+1,packet.tokens.length-1);draw();}};$('#p-back').onclick=()=>{stop();step=Math.max(step-1,0);draw();};$('#p-reset').onclick=()=>{stop();step=0;draw();};$('#p-position').oninput=e=>{stop();step=+e.target.value;draw();};$('#p-export').onclick=()=>{if(packet)download('smbus-packet.json',JSON.stringify({spec:'3.3',protocol:$('#proto').value,...packet},null,2),'application/json');};$('#p-svg').onclick=()=>{if(packet)download('smbus-wave.svg',$('#p-wave').innerHTML,'image/svg+xml');};build();}
function initPec(){$('#pec-lab').innerHTML=lab('CRC-8 / SMBus 계산기',`<label for="pec-bytes">주소+R/W를 포함한 바이트 (hex · PEC 자체 제외)</label><input id="pec-bytes" type="text" value="16 09 17 34 12" style="width:100%;margin:10px 0"><div class="toolbar"><label>수신 PEC (선택, hex)<input id="pec-received" type="text" size="5" maxlength="2" placeholder="00"></label><button class="btn" id="pec-example">Read Word 예제</button><button class="btn" id="pec-flip">마지막 데이터의 bit 0 반전</button></div><div id="pec-result" aria-live="polite"></div>`);const f=()=>{try{const bytes=SMB.parseBytes($('#pec-bytes').value);if(bytes.length>1024)throw Error('이 실험은 1024바이트 이하로 입력하세요.');const crc=SMB.crc8(bytes),trace=SMB.crcTrace(bytes),received=$('#pec-received').value;let compare='';if(received){if(!/^[a-f0-9]{1,2}$/i.test(received))throw Error('수신 PEC는 00–FF입니다.');compare=`<b class="${crc===parseInt(received,16)?'good':'bad'}">${crc===parseInt(received,16)?'MATCH':'MISMATCH'}</b>`;}$('#pec-result').innerHTML=`<p class="metric">PEC 0x${SMB.hex(crc)} ${compare}</p><p class="hint">Read Word 예제: 16=주소+W, 09=command, 17=주소+R, 34 12=data. START·repeated START·ACK는 입력하지 않습니다.</p>`+table(['순서','입력 byte','누적 CRC'],bytes.map((v,i)=>[i+1,'0x'+SMB.hex(v),'0x'+SMB.hex(trace[i])]))}catch(e){$('#pec-result').textContent=e.message;}};$('#pec-bytes').oninput=f;$('#pec-received').oninput=f;$('#pec-example').onclick=()=>{$('#pec-bytes').value='16 09 17 34 12';$('#pec-received').value='';f();};$('#pec-flip').onclick=()=>{try{let b=SMB.parseBytes($('#pec-bytes').value);$('#pec-received').value=SMB.hex(SMB.crc8(b));b[b.length-1]^=1;$('#pec-bytes').value=b.map(v=>SMB.hex(v)).join(' ');f();}catch{f();}};f();}
function addressInfo(n){if(n===0)return 'General Call (W) / START byte (R), I²C 예약';if(n===1)return 'CBUS 예약';if(n===2)return '다른 버스 형식 예약';if(n===3)return '미래 용도 예약';if(n>=4&&n<=7)return 'I²C high-speed controller code 예약';const names={8:'SMBus Host',9:'Smart Battery Charger',10:'Smart Battery Selector / System Manager',11:'Smart Battery',12:'Alert Response Address · Read 전용',40:'PMBus ZONE READ (0x28) · Read 전용',44:'이전 LCD Contrast 예약',45:'이전 CCFL Backlight 예약',55:'PMBus ZONE WRITE (0x37) · Write 전용',68:'이전 VGA Graphics Controller 예약',97:'SMBus ARP Device Default Address'};if(names[n])return names[n];if(n>=64&&n<=67)return '이전 PCMCIA controller 예약';if(n>=72&&n<=75)return 'Prototype address · 양산 장치 할당 금지';if(n>=120&&n<=123)return '10비트 target addressing · SMBus 범위 밖';if(n>=124)return '미래 용도 예약';return 'Table 17의 예약/사전 할당 항목 없음 · 실제 충돌/장치 요구는 별도 확인';}
function initAddress(){let n=11;$('#address-lab').innerHTML=lab('7비트 주소 지도',`<div class="address-grid" id="addr-grid"></div><div id="addr-result" style="margin-top:20px" aria-live="polite"></div><p class="hint">초록: Table 17에 별도 항목 없음 / 회색: 예약 또는 사전 할당. 자유롭게 사용해도 된다는 보증은 아닙니다.</p>`);const f=()=>{$('#addr-grid').innerHTML=Array.from({length:128},(_,i)=>`<button data-addr="${i}" class="${addressInfo(i).startsWith('Table')?'':'reserved'} ${i===n?'chosen':''}" aria-label="주소 0x${SMB.hex(i)}">${SMB.hex(i)}</button>`).join('');$('#addr-grid').querySelectorAll('button').forEach(b=>b.onclick=()=>{n=+b.dataset.addr;f();});$('#addr-result').innerHTML=`<p class="metric">7-bit 0x${SMB.hex(n)}</p><p>${addressInfo(n)}</p><p class="mono">${n.toString(2).padStart(7,'0')} + W(0) = 0x${SMB.hex(n<<1)}<br>${n.toString(2).padStart(7,'0')} + R(1) = 0x${SMB.hex((n<<1)|1)}</p>`;};f();$('#udid-lab').innerHTML=lab('UDID field decoder',`<label for="udid">128비트 UDID · hex 32자리</label><input id="udid" type="text" style="width:100%;margin:10px 0" value="81081234567800070000000000000001"><div id="udid-result"></div>`);const u=()=>{const s=$('#udid').value.replace(/\s/g,'');if(!/^[a-f0-9]{32}$/i.test(s)){$('#udid-result').textContent='공백을 제외한 16진수 32자리를 입력하세요.';return;}const fields=[['Device Capabilities',0,2],['Version / Revision',2,4],['Vendor ID',4,8],['Device ID',8,12],['Interface',12,16],['Subsystem Vendor ID',16,20],['Subsystem Device ID',20,24],['Vendor-specific ID',24,32]],cap=parseInt(s.slice(0,2),16),ver=parseInt(s.slice(2,4),16),iface=parseInt(s.slice(12,16),16),smver=iface&15,versions={0:'1.0 (ARP에 사용 금지)',1:'1.1 (ARP에 사용 금지)',4:'2.0',5:'3.0',6:'3.1',7:'3.2'},warnings=[];if(cap&62)warnings.push('Capabilities reserved 비트가 0이 아닙니다.');if(ver&192||((ver>>3)&7)!==1)warnings.push('Version reserved/UDID version을 확인하세요.');if(iface&65280||!versions[smver])warnings.push('Interface 예약 비트/버전 코드가 있습니다.');if(s.slice(16,20)==='0000'&&s.slice(20,24)!=='0000')warnings.push('Subsystem Vendor=0이면 Device도 0이어야 합니다.');$('#udid-result').innerHTML=table(['필드','값'],fields.map(([a,b,c])=>[a,'0x'+s.slice(b,c).toUpperCase()]))+`<p>주소 유형: <b>${['Fixed','Dynamic persistent','Dynamic volatile','Random'][cap>>6]}</b> · PEC: ${cap&1?'지원 표시':'미상'}<br>UDID version ${(ver>>3)&7}, silicon revision ${ver&7} · SMBus ${versions[smver]||'예약 코드'}</p><p class="warn-text">${warnings.join(' ')}</p><p class="hint">필드 해석기이며 UDID의 전 세계 유일성·Vendor ID 등록 여부를 검증하지 않습니다.</p>`;};$('#udid').oninput=u;u();}
function initArp(){let state=0,devices=[{name:'Sensor A',udid:'81081234567800070000000000000003'},{name:'Sensor B',udid:'81081234567800070000000000000001'},{name:'Sensor C',udid:'81081234567800070000000000000002'}],chosen=-1,log=[];const reset=()=>{state=0;chosen=-1;log=['Power-on: 동적 비영속 장치 3개, AR=0 / AV=0.'];devices.forEach(d=>{d.ar=0;d.av=0;d.addr=null;});};reset();$('#arp-lab').innerHTML=lab('주소 할당을 한 단계씩',`<div class="toolbar"><button class="btn primary" id="arp-next">다음 단계 →</button><button class="btn" id="arp-reset">Power-on 초기화</button></div><div id="arp-state" aria-live="polite"></div><div id="arp-devices"></div><div class="card compact" id="arp-log"></div><p class="hint">모든 장치는 dynamic volatile, 예제 주소 pool은 0x20–0x22로 설정했습니다. 고정·영속 주소·오류 분기는 아래 본문과 원문 상태도를 참고하세요.</p>`);function draw(){$('#arp-next').disabled=state===4;$('#arp-state').innerHTML=`<p class="metric">${['준비','Get UDID','Assign Address','Get UDID','해결 완료'][state]}</p>`;$('#arp-devices').innerHTML=table(['장치','UDID (끝 8자리)','AR','AV','주소'],devices.map((d,i)=>[d.name+(i===chosen?' ← 선택':''),d.udid.slice(-8),d.ar,d.av,d.addr==null?'미할당':'0x'+SMB.hex(d.addr)]));$('#arp-log').innerHTML=log.map((s,i)=>`<div>${i+1}. ${s}</div>`).join('');}$('#arp-next').onclick=()=>{if(state===0){devices.forEach(d=>d.ar=0);log.push('0x61 / command 01h + PEC: Prepare to ARP → AR clear, AV 유지.');state=1;}else if(state===1||state===3){const remain=devices.filter(d=>!d.ar).sort((a,b)=>a.udid.localeCompare(b.udid));if(!remain.length){state=4;chosen=-1;log.push('General Get UDID: 응답 없음(NACK) → 이번 ARP 종료.');}else{chosen=devices.indexOf(remain[0]);state=2;log.push(`03h + PEC: ${remain[0].name}의 가장 낮은 UDID가 중재 승리. Count=11h, UDID 16B + FFh(미할당) 반환.`);}}else if(state===2){let d=devices[chosen];d.addr=0x20+devices.filter(d=>d.ar).length;d.ar=d.av=1;log.push(`04h + count 11h + UDID + 주소 + PEC: ${d.name} → 0x${SMB.hex(d.addr)}. ACK 확인, AR=AV=1, pool에 추가.`);state=3;chosen=-1;}draw();};$('#arp-reset').onclick=()=>{reset();draw();};draw();}
function initAlert(){let pending=[0x2a,0x12,0x35],log='세 장치가 SMBALERT#를 LOW로 구동했습니다.';$('#alert-lab').innerHTML=lab('Alert Response 중재',`<div class="toolbar"><button class="btn primary" id="alert-read">ARA 0x0C 읽기</button><button class="btn" id="alert-reset">동시 알림 재발생</button></div><div id="alert-state" aria-live="polite"></div>`);const f=()=>{$('#alert-read').disabled=!pending.length;$('#alert-state').innerHTML=`<p class="metric">SMBALERT# = ${pending.length?'LOW':'HIGH'}</p><p>대기 장치: ${pending.map(x=>'0x'+SMB.hex(x)).join(', ')||'없음'}</p><p class="compact">${log}</p>`;};$('#alert-read').onclick=()=>{let n=Math.min(...pending);pending=pending.filter(x=>x!==n);log=`0x19(ARA+R) → 응답 0x${SMB.hex(n<<1)} (주소 0x${SMB.hex(n)}, X=0 예제) → controller NACK → 해당 장치 alert 해제.`;f();};$('#alert-reset').onclick=()=>{pending=[0x2a,0x12,0x35];log='세 장치가 다시 SMBALERT#를 LOW로 구동했습니다.';f();};f();}
const checks=[['전기','VDD·VIH/VIL·VOL·sink 전류·pull-up current 확인'],['전기','전원 OFF leakage·역급전·I/O 내압 확인'],['전기','부하·배선·R 변경 시 rise/fall threshold 실측'],['AC','지원하는 모든 속도 클래스에서 fSMB / tLOW / tHIGH 확인'],['AC','START·repeated START·STOP·tBUF 측정'],['AC','송신기별 setup/hold와 probe skew 확인'],['AC','지원 클래스의 spike rejection 경계 실험'],['링크','각 비트 패턴·ACK/NACK 구동 주체 확인'],['링크','동시 controller 중재 및 패배 후 해제 확인'],['시간','연속 LOW 25 ms 경계·35 ms 준비 상태 확인'],['시간','Target 메시지별 누적 연장 25 ms 경계 확인'],['시간','Controller 바이트 구간별 누적 연장 10 ms 확인'],['시간','SMBDAT stuck LOW 권고 복구와 정상 거래 재개 확인'],['프로토콜','지원 프로토콜별 command/data/byte 순서 확인'],['프로토콜','Block 0·1·최대 지원 길이, count 불일치 실험'],['프로토콜','Write/Read 32·64 padding과 payload 순서 확인'],['PEC','정상·잘못된 PEC·PEC 미사용 혼합 시험'],['PEC','Repeated START 전체 CRC 및 마지막 NACK 위치 확인'],['ARP','UDID 필드·AR/AV POR 상태·PEC 확인'],['ARP','일반/Directed 명령·고정/영속/동적 유형별 분기 확인'],['ARP','중복 주소·hot-plug·장치 이탈·enumerator 동시성 시험'],['알림','지원 시 Host Notify / ARA 중재와 해제 확인'],['전원','지원 시 SMBSUS# 시퀀스·START wake-up 확인'],['전원','tPOR 500 ms 및 복귀 후 첫 메시지 확인'],['시스템','전압·온도·보드·상대 장치 조합의 회귀 결과 기록']];
function initCheck(){$('#check-lab').innerHTML=lab('Post-silicon checklist',`<div class="row"><span id="check-progress"></span><button class="btn" id="check-export">기록 JSON 저장</button></div><div class="checklist">${checks.map(([a,b],i)=>`<label><input type="checkbox" data-check="${i}" ${saved.checks.includes(i)?'checked':''}><span><small>${a}</small><br>${b}</span></label>`).join('')}</div>`);const f=()=>$('#check-progress').textContent=`${saved.checks.length} / ${checks.length}개 기록`;$('#check-lab').querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{const i=+e.dataset.check;saved.checks=e.checked?[...new Set([...saved.checks,i])]:saved.checks.filter(x=>x!==i);save();f();});$('#check-export').onclick=()=>download('smbus-study-record.json',JSON.stringify({spec:'3.3',exported:new Date().toISOString(),checklist:checks.map(([category,item],i)=>({category,item,checked:saved.checks.includes(i)})),notes:saved.notes,completedChapters:saved.done},null,2),'application/json');f();}
$('#theme').onclick=()=>{saved.dark=!document.body.classList.contains('dark');document.body.classList.toggle('dark',saved.dark);save();};document.body.classList.toggle('dark',!!saved.dark);$('#menu').onclick=()=>{$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',$('#sidebar').classList.contains('open'));};$('#search').oninput=e=>{const q=e.target.value.trim().toLowerCase();if(!q){render();return;}cleanup();const results=chapters.filter(c=>(c.title+' '+c.desc+' '+c.body().replace(/<[^>]+>/g,' ')).toLowerCase().includes(q));$('#main').innerHTML=`<div class="eyebrow">SEARCH THE BOOK</div><h1>“${esc(e.target.value)}” 검색</h1><p class="hint">${results.length}개 챕터</p>${results.map(c=>`<a class="card card-link search-result" href="#${c.id}"><h3>${c.title}</h3><p>${c.desc}</p><small>${c.section}</small></a>`).join('')||'<p>일치하는 내용이 없습니다. 한국어 또는 영문 규격 용어로 검색해 보세요.</p>'}`;};window.addEventListener('hashchange',render);document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&a.getAttribute('href')===location.hash&&a.getAttribute('href')!=='#main')render();});render();
